#define F(a, b, c) file_fmtcheck((a), (b), (c), __FILE__, __LINE__)

private const char * __attribute__((__format_arg__(3)))
file_fmtcheck(struct magic_set *ms, const struct magic *m, const char *def,
        const char *file, size_t line)
{
        const char *ptr = fmtcheck(m->desc, def);
        if (ptr == def)
                file_magerror(ms,
                    "%s, %" SIZE_T_FORMAT "u: format `%s' does not match"
                    " with `%s'", file, line, m->desc, def);
        return ptr;
}
#else
#define F(a, b, c) fmtcheck((b)->desc, (c))
#endif

/*
 * Go through the whole list, stopping if you find a match.  Process all
 * the continuations of that match before returning.
 *
 * We support multi-level continuations:
 *
 *      At any time when processing a successful top-level match, there is a
 *      current continuation level; it represents the level of the last
 *      successfully matched continuation.
 *
 *      Continuations above that level are skipped as, if we see one, it
 *      means that the continuation that controls them - i.e, the
 *      lower-level continuation preceding them - failed to match.
 *
 *      Continuations below that level are processed as, if we see one,
 *      it means we've finished processing or skipping higher-level
 *      continuations under the control of a successful or unsuccessful
 *      lower-level continuation, and are now seeing the next lower-level
 *      continuation and should process it.  The current continuation
 *      level reverts to the level of the one we're seeing.
 *
 *      Continuations at the current level are processed as, if we see
 *      one, there's no lower-level continuation that may have failed.
 *
 *      If a continuation matches, we bump the current continuation level
 *      so that higher-level continuations are processed.
 */
private int
match(struct magic_set *ms, struct magic *magic, uint32_t nmagic,
    const unsigned char *s, size_t nbytes, size_t offset, int mode, int text,
    int flip, uint16_t *indir_count, uint16_t *name_count,
    int *printed_something, int *need_separator, int *returnval)
{
        uint32_t magindex = 0;
        unsigned int cont_level = 0;
        int returnvalv = 0, e; /* if a match is found it is set to 1*/
        int firstline = 1; /* a flag to print X\n  X\n- X */
        int print = (ms->flags & MAGIC_NODESC) == 0;

        if (returnval == NULL)
                returnval = &returnvalv;

        if (file_check_mem(ms, cont_level) == -1)
                return -1;

        for (magindex = 0; magindex < nmagic; magindex++) {
                int flush = 0;
                struct magic *m = &magic[magindex];

                if (m->type != FILE_NAME)
                if ((IS_STRING(m->type) &&
#define FLT (STRING_BINTEST | STRING_TEXTTEST)
                     ((text && (m->str_flags & FLT) == STRING_BINTEST) ||
                      (!text && (m->str_flags & FLT) == STRING_TEXTTEST))) ||
                    (m->flag & mode) != mode) {
flush:
                        /* Skip sub-tests */
                        while (magindex < nmagic - 1 &&
                            magic[magindex + 1].cont_level != 0)
                                magindex++;
                        cont_level = 0;
                        continue; /* Skip to next top-level test*/
                }

                ms->offset = m->offset;
                ms->line = m->lineno;

                /* if main entry matches, print it... */
                switch (mget(ms, s, m, nbytes, offset, cont_level, mode, text,
                    flip, indir_count, name_count,
                    printed_something, need_separator, returnval)) {
                case -1:
                        return -1;
                case 0:
                        flush = m->reln != '!';
                        break;
                default:
                        if (m->type == FILE_INDIRECT)
                                *returnval = 1;

                        switch (magiccheck(ms, m)) {
                        case -1:
                                return -1;
                        case 0:
                                flush++;
                                break;
                        default:
                                flush = 0;
                                break;
                        }
                        break;
                }
                if (flush) {
                        /*
                         * main entry didn't match,
                         * flush its continuations
                         */
                        goto flush;
                }

                if ((e = handle_annotation(ms, m, firstline)) != 0) {
                        *need_separator = 1;
                        *printed_something = 1;
                        *returnval = 1;
                        return e;
                }

                /*
                 * If we are going to print something, we'll need to print
                 * a blank before we print something else.
                 */
                if (*m->desc) {
                        *need_separator = 1;
                        *printed_something = 1;
                        if (print_sep(ms, firstline) == -1)
                                return -1;
                }


                if (print && mprint(ms, m) == -1)
                        return -1;

                switch (moffset(ms, m, nbytes, &ms->c.li[cont_level].off)) {
                case -1:
                case 0:
                        goto flush;
--- mid ---
                        goto flush;
                default:
                        break;
                }

                /* and any continuations that match */
                if (file_check_mem(ms, ++cont_level) == -1)
                        return -1;

                while (magindex + 1 < nmagic &&
                    magic[magindex + 1].cont_level != 0) {
                        m = &magic[++magindex];
                        ms->line = m->lineno; /* for messages */

                        if (cont_level < m->cont_level)
                                continue;
                        if (cont_level > m->cont_level) {
                                /*
                                 * We're at the end of the level
                                 * "cont_level" continuations.
                                 */
                                cont_level = m->cont_level;
                        }
                        ms->offset = m->offset;
                        if (m->flag & OFFADD) {
                                ms->offset +=
                                    ms->c.li[cont_level - 1].off;
                        }

#ifdef ENABLE_CONDITIONALS
                        if (m->cond == COND_ELSE ||
                            m->cond == COND_ELIF) {
                                if (ms->c.li[cont_level].last_match == 1)
                                        continue;
                        }
#endif
                        switch (mget(ms, s, m, nbytes, offset, cont_level, mode,
                            text, flip, indir_count, name_count,
                            printed_something, need_separator, returnval)) {
                        case -1:
                                return -1;
                        case 0:
                                if (m->reln != '!')
                                        continue;
                                flush = 1;
                                break;
                        default:
                                if (m->type == FILE_INDIRECT)
                                        *returnval = 1;
                                flush = 0;
                                break;
                        }

                        switch (flush ? 1 : magiccheck(ms, m)) {
                        case -1:
                                return -1;
                        case 0:
#ifdef ENABLE_CONDITIONALS
                                ms->c.li[cont_level].last_match = 0;
#endif
                                break;
                        default:
#ifdef ENABLE_CONDITIONALS
                                ms->c.li[cont_level].last_match = 1;
#endif
                                if (m->type == FILE_CLEAR)
                                        ms->c.li[cont_level].got_match = 0;
                                else if (ms->c.li[cont_level].got_match) {
                                        if (m->type == FILE_DEFAULT)
                                                break;
                                } else
                                        ms->c.li[cont_level].got_match = 1;

                                if ((e = handle_annotation(ms, m, firstline)) != 0) {
                                        *need_separator = 1;
                                        *printed_something = 1;
                                        *returnval = 1;
                                        return e;
                                }
                                /*
                                 * If we are going to print something,
                                 * make sure that we have a separator first.
                                 */
                                if (*m->desc) {
                                        if (!*printed_something) {
                                                *printed_something = 1;
                                                if (print_sep(ms, firstline)
                                                    == -1)
                                                        return -1;
                                        }
                                }
                                /*
                                 * This continuation matched.  Print
                                 * its message, with a blank before it
                                 * if the previous item printed and
                                 * this item isn't empty.
                                 */
                                /* space if previous printed */
                                if (*need_separator
                                    && ((m->flag & NOSPACE) == 0)
                                    && *m->desc) {
                                        if (print &&
                                            file_printf(ms, " ") == -1)
                                                return -1;
                                        *need_separator = 0;
                                }
                                if (print && mprint(ms, m) == -1)
                                        return -1;

                                switch (moffset(ms, m, nbytes,
                                    &ms->c.li[cont_level].off)) {
                                case -1:
                                case 0:
                                        flush = 1;
                                        cont_level--;
                                        break;
                                default:
                                        break;
                                }

                                if (*m->desc)
                                        *need_separator = 1;

                                /*
                                 * If we see any continuations
                                 * at a higher level,
                                 * process them.
                                 */
                                if (file_check_mem(ms, ++cont_level) == -1)
                                        return -1;
                                break;
                        }
                }
                if (*printed_something) {
                        firstline = 0;
                        if (print)
                                *returnval = 1;
                }
                if ((ms->flags & MAGIC_CONTINUE) == 0 && *printed_something) {
                        return *returnval; /* don't keep searching */
                }
                cont_level = 0;
        }
        return *returnval;  /* This is hit if -k is set or there is no match */
}

private int
check_fmt(struct magic_set *ms, struct magic *m)
{
        file_regex_t rx;
        int rc, rv = -1;

        if (strchr(m->desc, '%') == NULL)
                return 0;

        rc = file_regcomp(&rx, "%[-0-9\\.]*s", REG_EXTENDED|REG_NOSUB);
        if (rc) {
                file_regerror(&rx, rc, ms);
        } else {
                rc = file_regexec(&rx, m->desc, 0, 0, 0);
                rv = !rc;
        }
        file_regfree(&rx);
        return rv;
}

#ifndef HAVE_STRNDUP
char * strndup(const char *, size_t);

char *
strndup(const char *str, size_t n)
{
        size_t len;
        char *copy;

        for (len = 0; len < n && str[len]; len++)
                continue;
        if ((copy = malloc(len + 1)) == NULL)
                return NULL;
        (void)memcpy(copy, str, len);
        copy[len] = '\0';
        return copy;
}
#endif /* HAVE_STRNDUP */

private int32_t
mprint(struct magic_set *ms, struct magic *m)
{
        uint64_t v;
        float vf;
        double vd;
        int64_t t = 0;
        char buf[128], tbuf[26], sbuf[512];
        union VALUETYPE *p = &ms->ms_value;

        switch (m->type) {
        case FILE_BYTE:
                v = file_signextend(ms, m, (uint64_t)p->b);
                switch (check_fmt(ms, m)) {
                case -1:
                        return -1;
                case 1:
                        (void)snprintf(buf, sizeof(buf), "%d",
                            (unsigned char)v);
                        if (file_printf(ms, F(ms, m, "%s"), buf) == -1)
                                return -1;
                        break;
                default:
                        if (file_printf(ms, F(ms, m, "%d"),
                            (unsigned char) v) == -1)
                                return -1;
                        break;
                }
                t = ms->offset + sizeof(char);
                break;

        case FILE_SHORT:
        case FILE_BESHORT:
        case FILE_LESHORT:
                v = file_signextend(ms, m, (uint64_t)p->h);
                switch (check_fmt(ms, m)) {
                case -1:
                        return -1;
                case 1:
                        (void)snprintf(buf, sizeof(buf), "%u",
                            (unsigned short)v);
                        if (file_printf(ms, F(ms, m, "%s"), buf) == -1)
                                return -1;
                        break;
                default:
                        if (file_printf(ms, F(ms, m, "%u"),
                            (unsigned short) v) == -1)
                                return -1;
                        break;
                }
                t = ms->offset + sizeof(short);
                break;

        case FILE_LONG:
        case FILE_BELONG:
        case FILE_LELONG:
        case FILE_MELONG:
                v = file_signextend(ms, m, (uint64_t)p->l);
                switch (check_fmt(ms, m)) {
                case -1:
                        return -1;
                case 1:
                        (void)snprintf(buf, sizeof(buf), "%u", (uint32_t) v);
                        if (file_printf(ms, F(ms, m, "%s"), buf) == -1)
                                return -1;
                        break;
                default:
                        if (file_printf(ms, F(ms, m, "%u"), (uint32_t) v) == -1)
                                return -1;
                        break;
                }
                t = ms->offset + sizeof(int32_t);
                break;

        case FILE_QUAD:
        case FILE_BEQUAD:
        case FILE_LEQUAD:
                v = file_signextend(ms, m, p->q);
                switch (check_fmt(ms, m)) {
                case -1:
                        return -1;
                case 1:
                        (void)snprintf(buf, sizeof(buf), "%" INT64_T_FORMAT "u",
                            (unsigned long long)v);
                        if (file_printf(ms, F(ms, m, "%s"), buf) == -1)
                                return -1;
                        break;
                default:
                        if (file_printf(ms, F(ms, m, "%" INT64_T_FORMAT "u"),
                            (unsigned long long) v) == -1)
                                return -1;
                        break;
                }
                t = ms->offset + sizeof(int64_t);
                break;

        case FILE_STRING:
        case FILE_PSTRING:
        case FILE_BESTRING16:
        case FILE_LESTRING16:
                if (m->reln == '=' || m->reln == '!') {
                        if (file_printf(ms, F(ms, m, "%s"),
                            file_printable(sbuf, sizeof(sbuf), m->value.s))
                            == -1)
                                return -1;
                        t = ms->offset + m->vallen;
                }
                else {
                        char *str = p->s;

                        /* compute t before we mangle the string? */
                        t = ms->offset + strlen(str);

                        if (*m->value.s == '\0')
                                str[strcspn(str, "\r\n")] = '\0';

                        if (m->str_flags & STRING_TRIM) {
                                char *last;
                                while (isspace((unsigned char)*str))
                                        str++;
                                last = str;
                                while (*last)
                                        last++;
                                --last;
                                while (isspace((unsigned char)*last))
                                        last--;
                                *++last = '\0';
                        }

                        if (file_printf(ms, F(ms, m, "%s"),
                            file_printable(sbuf, sizeof(sbuf), str)) == -1)
                                return -1;

                        if (m->type == FILE_PSTRING)
                                t += file_pstring_length_size(m);
                }
                break;

        case FILE_DATE:
        case FILE_BEDATE:
        case FILE_LEDATE:
        case FILE_MEDATE:
                if (file_printf(ms, F(ms, m, "%s"),
                    file_fmttime(p->l, 0, tbuf)) == -1)
                        return -1;
                t = ms->offset + sizeof(uint32_t);
                break;

        case FILE_LDATE:
        case FILE_BELDATE:
        case FILE_LELDATE:
        case FILE_MELDATE:
                if (file_printf(ms, F(ms, m, "%s"),
                    file_fmttime(p->l, FILE_T_LOCAL, tbuf)) == -1)
                        return -1;
                t = ms->offset + sizeof(uint32_t);
                break;

        case FILE_QDATE:
        case FILE_BEQDATE:
        case FILE_LEQDATE:
                if (file_printf(ms, F(ms, m, "%s"),
                    file_fmttime(p->q, 0, tbuf)) == -1)
                        return -1;
                t = ms->offset + sizeof(uint64_t);
                break;

        case FILE_QLDATE:
        case FILE_BEQLDATE:
        case FILE_LEQLDATE:
                if (file_printf(ms, F(ms, m, "%s"),
                    file_fmttime(p->q, FILE_T_LOCAL, tbuf)) == -1)
                        return -1;
                t = ms->offset + sizeof(uint64_t);
                break;

