public const char *
magic_error(struct magic_set *ms)
{
        if (ms == NULL)
                return "Magic database is not open";
        return (ms->event_flags & EVENT_HAD_ERR) ? ms->o.buf : NULL;
}

public int
magic_errno(struct magic_set *ms)
{
        if (ms == NULL)
                return EINVAL;
        return (ms->event_flags & EVENT_HAD_ERR) ? ms->error : 0;
}

public int
magic_getflags(struct magic_set *ms)
{
        if (ms == NULL)
                return -1;

        return ms->flags;
}

public int
magic_setflags(struct magic_set *ms, int flags)
{
        if (ms == NULL)
                return -1;
#if !defined(HAVE_UTIME) && !defined(HAVE_UTIMES)
        if (flags & MAGIC_PRESERVE_ATIME)
                return -1;
#endif
        ms->flags = flags;
        return 0;
}

public int
magic_version(void)
{
        return MAGIC_VERSION;
}

public int
magic_setparam(struct magic_set *ms, int param, const void *val)
{
        switch (param) {
        case MAGIC_PARAM_INDIR_MAX:
                ms->indir_max = (uint16_t)*(const size_t *)val;
                return 0;
        case MAGIC_PARAM_NAME_MAX:
                ms->name_max = (uint16_t)*(const size_t *)val;
                return 0;
        case MAGIC_PARAM_ELF_PHNUM_MAX:
                ms->elf_phnum_max = (uint16_t)*(const size_t *)val;
                return 0;
        case MAGIC_PARAM_ELF_SHNUM_MAX:
                ms->elf_shnum_max = (uint16_t)*(const size_t *)val;
                return 0;
        case MAGIC_PARAM_ELF_NOTES_MAX:
                ms->elf_notes_max = (uint16_t)*(const size_t *)val;
                return 0;
        case MAGIC_PARAM_REGEX_MAX:
                ms->elf_notes_max = (uint16_t)*(const size_t *)val;
                return 0;
        case MAGIC_PARAM_BYTES_MAX:
